/*
 * Mapbox Storytelling engine, ported from https://github.com/mapbox/storytelling (BSD-3-Clause, © Mapbox).
 * The chapter `config` is generated by Django (Story + Chapter models) and embedded in the page.
 * Additions: FloodStory hooks for data layers, progress bar, runtime auto-play toggle, explore mode.
 */
var initLoad = true;
var layerTypes = {
  'fill': ['fill-opacity'],
  'line': ['line-opacity'],
  'circle': ['circle-opacity', 'circle-stroke-opacity'],
  'symbol': ['icon-opacity', 'text-opacity'],
  'raster': ['raster-opacity'],
  'fill-extrusion': ['fill-extrusion-opacity'],
  'heatmap': ['heatmap-opacity']
};

var alignments = {
  'left': 'lefty',
  'center': 'centered',
  'right': 'righty',
  'full': 'fully'
};

function getLayerPaintType(layer) {
  var layerType = map.getLayer(layer).type;
  return layerTypes[layerType];
}

function setLayerOpacity(layer) {
  if (!map.getLayer(layer.layer)) return;
  var paintProps = getLayerPaintType(layer.layer);
  paintProps.forEach(function (prop) {
    var options = {};
    if (layer.duration) {
      var transitionProp = prop + "-transition";
      options = { "duration": layer.duration };
      map.setPaintProperty(layer.layer, transitionProp, options);
    }
    map.setPaintProperty(layer.layer, prop, layer.opacity, options);
  });
}

var story = document.getElementById('story');
var features = document.createElement('div');
features.setAttribute('id', 'features');

var header = document.createElement('div');

if (config.title) {
  var titleText = document.createElement('h1');
  titleText.innerText = config.title;
  header.appendChild(titleText);
}

if (config.subtitle) {
  var subtitleText = document.createElement('h2');
  subtitleText.innerText = config.subtitle;
  header.appendChild(subtitleText);
}

if (config.byline) {
  var bylineText = document.createElement('p');
  bylineText.innerText = config.byline;
  header.appendChild(bylineText);
}

if (header.innerText.length > 0) {
  var scrollHint = document.createElement('div');
  scrollHint.className = 'scroll-hint';
  scrollHint.innerHTML = 'Scroll to begin <span>↓</span>';
  header.appendChild(scrollHint);
  header.classList.add(config.theme);
  header.setAttribute('id', 'header');
  story.appendChild(header);
}

config.chapters.forEach((record, idx) => {
  var container = document.createElement('div');
  var chapter = document.createElement('div');

  if (record.title) {
    var title = document.createElement('h3');
    title.innerText = record.title;
    chapter.appendChild(title);
  }

  if (record.image) {
    var image = new Image();
    image.src = record.image;
    image.alt = record.title || '';
    image.loading = 'lazy';
    chapter.appendChild(image);
  }

  if (record.description) {
    var story = document.createElement('div');
    story.className = 'description';
    story.innerHTML = record.description;
    chapter.appendChild(story);
  }

  container.setAttribute('id', record.id);
  container.classList.add('step');
  if (idx === 0) {
    container.classList.add('active');
  }

  chapter.classList.add(config.theme);
  container.appendChild(chapter);
  container.classList.add(alignments[record.alignment] || 'centered');
  if (record.hidden) {
    container.classList.add('hidden');
  }
  features.appendChild(container);
});

story.appendChild(features);

var footer = document.createElement('div');

if (config.footer) {
  var footerText = document.createElement('p');
  footerText.innerHTML = config.footer;
  footer.appendChild(footerText);
}

if (footer.innerText.length > 0) {
  footer.classList.add(config.theme);
  footer.setAttribute('id', 'footer');
  story.appendChild(footer);
}

if (!config.accessToken) {
  document.getElementById('no-token').hidden = false;
  throw new Error('MAPBOX_TOKEN is not configured');
}

/* Render-resolution cap. Mapbox reads window.devicePixelRatio through a live getter, so capping it
   here divides the number of pixels the GPU shades every frame (a 1.75x screen renders 2x fewer
   pixels at 1.25). Quality.lower() drops it again to 1.0 if the frame rate stays poor. */
window.Quality = {
  cap: 1.25,
  lowered: false,
  apply: function (cap) {
    this.cap = cap;
    Object.defineProperty(window, 'devicePixelRatio', { get: () => cap, configurable: true });
  },
  lower: function () {
    if (this.lowered) return;
    this.lowered = true;
    this.apply(1);
    if (window.map) { map.resize(); }
    if (window.FloodStory) FloodStory.lowerTerrain();
    console.info('[flood-story] low frame rate - reduced render resolution and terrain detail');
  },
};
if ((window.devicePixelRatio || 1) > Quality.cap) Quality.apply(Quality.cap);

mapboxgl.accessToken = config.accessToken;

var map = new mapboxgl.Map({
  container: 'map',
  style: config.style,
  center: config.chapters[0].location.center,
  zoom: config.chapters[0].location.zoom,
  bearing: config.chapters[0].location.bearing,
  pitch: config.chapters[0].location.pitch,
  interactive: true,          // handlers are disabled below and re-enabled in explore mode
  projection: config.projection,
  renderWorldCopies: false,   // one copy of the world is enough for a single-country story
  fadeDuration: 0,            // no label cross-fade work during camera flights
  maxTileCacheSize: 40        // this story revisits few areas; a big cache just costs memory
});
var MAP_HANDLERS = ['scrollZoom', 'boxZoom', 'dragRotate', 'dragPan', 'keyboard', 'doubleClickZoom', 'touchZoomRotate'];
MAP_HANDLERS.forEach(function (h) { map[h].disable(); });

// Create a inset map if enabled in config
if (config.inset) {
  map.addControl(
    new GlobeMinimap({ ...config.insetOptions }),
    config.insetPosition
  );
}

if (config.showMarkers) {
  var marker = new mapboxgl.Marker({ color: config.markerColor });
  marker.setLngLat(config.chapters[0].location.center).addTo(map);
}

// instantiate the scrollama
var scroller = scrollama();
var currentChapter = 0;

map.on("load", function () {
  if (config.use3dTerrain) {
    map.addSource('mapbox-dem', {
      'type': 'raster-dem',
      'url': 'mapbox://mapbox.mapbox-terrain-dem-v1',
      'tileSize': 512,
      // 12 instead of Mapbox's 14: the story never gets closer than ~zoom 10, and each extra
      // DEM level quadruples the terrain mesh work for detail that is not visible here.
      'maxzoom': 12
    });
    // Terrain itself is switched on per chapter by FloodStory.applyTerrain - enabling it for the
    // whole story keeps DEM tiles loading and re-projecting on every frame, which is the single
    // biggest cost on a laptop GPU.

    // add a sky layer that will show when the map is highly pitched
    map.addLayer({
      'id': 'sky',
      'type': 'sky',
      'paint': {
        'sky-type': 'atmosphere',
        'sky-atmosphere-sun': [0.0, 0.0],
        'sky-atmosphere-sun-intensity': 15
      }
    });
  };

  FloodStory.addLayers(map).then(function () {
    // setup the instance, pass callback functions
    scroller
      .setup({
        step: '.step',
        offset: 0.5,
        progress: true
      })
      .onStepEnter(async response => {
        var current_chapter = config.chapters.findIndex(chap => chap.id === response.element.id);
        var chapter = config.chapters[current_chapter];
        currentChapter = current_chapter;

        response.element.classList.add('active');
        map[chapter.mapAnimation || 'flyTo'](chapter.location);

        if (config.showMarkers) {
          marker.setLngLat(chapter.location.center);
        }
        FloodStory.beforeChapter(chapter, current_chapter);
        if (chapter.onChapterEnter.length > 0) {
          chapter.onChapterEnter.forEach(setLayerOpacity);
        }
        if (chapter.callback && typeof window[chapter.callback] === 'function') {
          window[chapter.callback]();
        }
        if (chapter.rotateAnimation) {
          map.once('moveend', () => {
            const rotateNumber = map.getBearing();
            map.rotateTo(rotateNumber + 180, {
              duration: 30000, easing: function (t) {
                return t;
              }
            });
          });
        }
        if (config.auto) {
          var next_chapter = (current_chapter + 1) % config.chapters.length;
          map.once('moveend', () => {
            setTimeout(() => {
              if (!config.auto || currentChapter !== current_chapter) return;
              document.querySelectorAll('[data-scrollama-index="' + next_chapter.toString() + '"]')[0]
                .scrollIntoView({ behavior: 'smooth', block: 'center' });
            }, 5000); // linger so the chapter can be read
          });
        }
      })
      .onStepExit(response => {
        var chapter = config.chapters.find(chap => chap.id === response.element.id);
        response.element.classList.remove('active');
        if (chapter.onChapterExit.length > 0) {
          chapter.onChapterExit.forEach(setLayerOpacity);
        }
      });

    if (config.auto) {
      document.querySelectorAll('[data-scrollama-index="0"]')[0].scrollIntoView();
    }
  });
});

window.addEventListener('resize', function () { scroller.resize(); });

// ---- runtime controls (auto-play toggle and explore hand-off)
window.StoryEngine = {
  setAuto: function (on) {
    config.auto = on;
    if (on) {
      var next = Math.min(currentChapter + 1, config.chapters.length - 1);
      document.querySelectorAll('[data-scrollama-index="' + next + '"]')[0]
        .scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
  },
  setInteractive: function (on) {
    MAP_HANDLERS.forEach(function (h) { map[h][on ? 'enable' : 'disable'](); });
  },
  returnToChapter: function () {
    var chapter = config.chapters[currentChapter];
    map.flyTo(chapter.location);
  },
  current: function () { return currentChapter; }
};
